/**
 * Reporting something a model wrote (app store rules for generative AI:
 * Microsoft Store 11.16, Google Play's AI-generated content policy). Every
 * screen that shows AI output offers Report; this builds what is sent: a
 * snapshot of the text as the learner saw it, the reason, an optional note,
 * and the ids the server resolves as the learner (the AI job, the Lex
 * message, the word). The server keeps the snapshot so a report can be read
 * after the card was edited.
 */
import type { Example, Word } from '@lexpad/core';
import { ai } from '@/api/endpoints.js';
import type { ApiAiReportInput, ApiAiReportReason, ApiAiReportSurface } from '@/api/types.js';
import type { WordDraft } from '@/db/mutations.js';
import { platform } from '@/lib/platform/index.js';

/** The longest note, in characters: the contract's AiReportInput.note. */
export const REPORT_NOTE_MAX = 500;
/** The longest snapshot, in characters: the contract's AiReportInput.snapshot. */
export const REPORT_SNAPSHOT_MAX = 4000;
/** The longest headword the contract accepts. */
const HEADWORD_MAX = 200;

/** The reasons, in the order the sheet lists them. */
export const REPORT_REASONS: readonly ApiAiReportReason[] = ['offensive', 'wrong', 'sexual', 'other'];

/** What is being reported, as the screen that shows it knows it. */
export interface ReportTarget {
  surface: ApiAiReportSurface;
  /** The text as shown. For a Lex answer the server reads its own copy. */
  snapshot: string;
  headword?: string | undefined;
  targetLang?: string | undefined;
  meaningLang?: string | undefined;
  wordId?: string | undefined;
  lexMessageId?: string | undefined;
  aiJobId?: string | undefined;
}

const VERSION = /^[0-9A-Za-z][0-9A-Za-z.+_-]{0,31}$/;
const LANG = /^[a-z]{2,3}(-[0-9A-Za-z]{2,8})?$/;
const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/;
// Characters the server refuses (every control but a line break and a tab).
// eslint-disable-next-line no-control-regex
const CONTROL = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g;

/** Cuts text to n characters (code points, so Persian and emoji count as one). */
export function cap(text: string, n: number): string {
  const chars = [...text];
  return chars.length <= n ? text : chars.slice(0, n).join('');
}

/** Text as it may be sent: no control characters, trimmed, within n characters. */
export function clean(text: string, n: number): string {
  return cap(text.replace(/\r\n?/g, '\n').replace(CONTROL, '').trim(), n);
}

/** Lines joined, empty ones left out, within the snapshot's limit. */
export function snapshotOf(lines: readonly (string | undefined | false)[]): string {
  return clean(
    lines.filter((line): line is string => typeof line === 'string' && line.trim() !== '').join('\n'),
    REPORT_SNAPSHOT_MAX,
  );
}

function phraseLine(
  label: string,
  items: readonly { text: string; translation?: string | undefined }[],
): string {
  return `${label}: ${items.map((p) => (p.translation ? `${p.text} — ${p.translation}` : p.text)).join('; ')}`;
}

/** A card as the model wrote it (Fill with AI, Improve, the list of AI cards). */
export function cardSnapshot(card: WordDraft): string {
  const head = [card.correction ?? card.headword, card.pos, card.level, card.pronunciation]
    .filter((part) => part !== undefined && part !== '')
    .join(' · ');
  const senses = [
    {
      meaning: card.meaning,
      gloss: card.gloss,
      examples: [
        ...(card.example ? [{ sentence: card.example, translation: card.translation }] : []),
        ...(card.moreExamples ?? []),
      ],
    },
    ...(card.extraMeanings ?? []).map((sense) => ({
      meaning: sense.meaning,
      gloss: sense.gloss,
      examples: sense.examples ?? [],
    })),
  ];
  return snapshotOf([
    head,
    ...senses.flatMap((sense, index) => [
      sense.meaning ? `${index + 1}. ${sense.meaning}` : undefined,
      sense.gloss,
      ...sense.examples.map((ex) =>
        ex.translation ? `“${ex.sentence}” — ${ex.translation}` : `“${ex.sentence}”`,
      ),
    ]),
    (card.collocations ?? []).length > 0 && `Collocations: ${(card.collocations ?? []).join('; ')}`,
    (card.expressions ?? []).length > 0 && phraseLine('Expressions', card.expressions ?? []),
    (card.relatedWords ?? []).length > 0 && phraseLine('Related', card.relatedWords ?? []),
    card.usageNote,
    card.spellingNote,
  ]);
}

/**
 * One sense of a word as its page shows it, for a sense the model wrote
 * into a word of another source: the headword, then the sense alone.
 */
export function senseSnapshot(
  word: Word,
  sense: { meaning: string; gloss?: string | undefined; examples?: readonly Example[] | undefined },
): string {
  return snapshotOf([
    word.correction ?? word.headword,
    sense.meaning,
    sense.gloss,
    ...(sense.examples ?? []).map((ex) =>
      ex.translation ? `“${ex.sentence}” — ${ex.translation}` : `“${ex.sentence}”`,
    ),
  ]);
}

/** A word's page: what it says now, which is what the learner is looking at. */
export function wordSnapshot(word: Word): string {
  const head = [word.correction ?? word.headword, word.pos, word.level, word.pronunciation]
    .filter((part) => part !== undefined && part !== '')
    .join(' · ');
  return snapshotOf([
    head,
    ...(word.meanings ?? []).flatMap((sense, index) => [
      `${index + 1}. ${sense.meaning}`,
      sense.gloss,
      ...(sense.examples ?? []).map((ex) =>
        ex.translation ? `“${ex.sentence}” — ${ex.translation}` : `“${ex.sentence}”`,
      ),
    ]),
    (word.collocations ?? []).length > 0 && `Collocations: ${(word.collocations ?? []).join('; ')}`,
    (word.expressions ?? []).length > 0 && phraseLine('Expressions', word.expressions ?? []),
    (word.relatedWords ?? []).length > 0 && phraseLine('Related', word.relatedWords ?? []),
    word.usageNote,
    word.spellingNote,
  ]);
}

/** The request body: every optional field only when it has a shape the server accepts. */
export function reportInput(target: ReportTarget, reason: ApiAiReportReason, note: string): ApiAiReportInput {
  const input: ApiAiReportInput = { surface: target.surface, reason };
  const snapshot = clean(target.snapshot, REPORT_SNAPSHOT_MAX);
  if (snapshot !== '') input.snapshot = snapshot;
  const trimmed = clean(note, REPORT_NOTE_MAX);
  if (trimmed !== '') input.note = trimmed;
  const headword = clean(target.headword ?? '', HEADWORD_MAX).replace(/[\n\t]+/g, ' ');
  if (headword !== '') input.headword = headword;
  if (target.targetLang !== undefined && LANG.test(target.targetLang)) input.targetLang = target.targetLang;
  if (target.meaningLang !== undefined && LANG.test(target.meaningLang))
    input.meaningLang = target.meaningLang;
  if (target.wordId !== undefined && ULID.test(target.wordId)) input.wordId = target.wordId;
  if (target.lexMessageId !== undefined && ULID.test(target.lexMessageId))
    input.lexMessageId = target.lexMessageId;
  if (target.aiJobId !== undefined && ULID.test(target.aiJobId)) input.aiJobId = target.aiJobId;
  const version = platform.env.appVersion;
  if (VERSION.test(version)) input.appVersion = version;
  return input;
}

/** Sends a report. The key stays the same across a retry of the same report. */
export async function sendReport(
  target: ReportTarget,
  reason: ApiAiReportReason,
  note: string,
  idempotencyKey: string,
): Promise<void> {
  await ai.report(reportInput(target, reason, note), idempotencyKey);
}

/* ---------------------------------------------------------------------------
 * The hand-off from the desktop app's card and the browser extension's card.
 * Neither can draw this sheet, so their Report link opens
 * `/report-ai#r=<base64url JSON>` in the app. The payload rides in the
 * fragment, which no server and no log ever sees.
 */

/** The longest fragment read, so a crafted link cannot make the page decode megabytes. */
const HANDOFF_MAX = 16_000;
const SURFACES: readonly ApiAiReportSurface[] = [
  'card',
  'word',
  'refine',
  'worth_keeping',
  'sentence',
  'lex',
];

function fromBase64Url(text: string): string {
  const base64 = text.replace(/-/g, '+').replace(/_/g, '/');
  const bytes = Uint8Array.from(atob(base64 + '='.repeat((4 - (base64.length % 4)) % 4)), (c) =>
    c.charCodeAt(0),
  );
  return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
}

/** Encodes a target for a hand-off link (what the desktop and extension cards do). */
export function encodeHandoff(target: ReportTarget): string {
  const bytes = new TextEncoder().encode(JSON.stringify(target));
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/**
 * Reads a hand-off fragment (`#r=…`). Anything that is not a well-formed
 * target with text to report is undefined, and the page says there is
 * nothing to report rather than guessing.
 */
export function decodeHandoff(hash: string): ReportTarget | undefined {
  const match = /^#?r=([A-Za-z0-9_-]+)$/.exec(hash);
  if (match?.[1] === undefined || match[1].length > HANDOFF_MAX) return undefined;
  let raw: unknown;
  try {
    raw = JSON.parse(fromBase64Url(match[1]));
  } catch {
    return undefined;
  }
  if (typeof raw !== 'object' || raw === null) return undefined;
  const value = raw as Record<string, unknown>;
  const text = (key: string): string | undefined => (typeof value[key] === 'string' ? value[key] : undefined);
  const surface = SURFACES.find((s) => s === value.surface);
  const snapshot = clean(text('snapshot') ?? '', REPORT_SNAPSHOT_MAX);
  // A Lex answer is reported from Lex itself; a hand-off carries text.
  if (surface === undefined || surface === 'lex' || snapshot === '') return undefined;
  return {
    surface,
    snapshot,
    headword: text('headword'),
    targetLang: text('targetLang'),
    meaningLang: text('meaningLang'),
    wordId: text('wordId'),
    aiJobId: text('aiJobId'),
  };
}
