import { useId, useRef, useState } from 'react';
import { newIdempotencyKey } from '@/api/client.js';
import { isApiError } from '@/api/errors.js';
import type { ApiAiReportReason } from '@/api/types.js';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { noteTrouble } from '@/features/review/review.js';
import { REPORT_NOTE_MAX, REPORT_REASONS, sendReport, type ReportTarget } from './report.js';
import styles from './Report.module.css';

const REASON_LABEL: Record<ApiAiReportReason, MessageKey> = {
  offensive: 'report.reason.offensive',
  wrong: 'report.reason.wrong',
  sexual: 'report.reason.sexual',
  other: 'report.reason.other',
};

/** When the note's counter appears: near the limit, not before. */
const NOTE_COUNT_FROM = REPORT_NOTE_MAX - 100;

type Phase = { kind: 'choosing' } | { kind: 'sending' } | { kind: 'sent' };

/**
 * Report something a model wrote: what is being reported (the text as the
 * learner saw it), why, an optional note, Send. Opened only by the learner's
 * own tap on Report; it never appears by itself. The reasons are a radio
 * group with arrow keys; Send waits for one. The same key goes with a retry,
 * so a second tap after a lost answer is stored once.
 */
export function ReportSheet({
  target,
  onClose,
  lead,
  send: deliver = (reason, note, key) => sendReport(target, reason, note, key),
}: {
  target: ReportTarget;
  onClose: () => void;
  /** What the sheet says first, when it is not about something the AI wrote. */
  lead?: string;
  /** Where the report goes, when not to the AI reports (a shared notebook's goes to the team's inbox). */
  send?: (reason: ApiAiReportReason, note: string, key: string) => Promise<void>;
}): React.JSX.Element {
  const id = useId();
  const [reason, setReason] = useState<ApiAiReportReason | undefined>(undefined);
  const [note, setNote] = useState('');
  const [phase, setPhase] = useState<Phase>({ kind: 'choosing' });
  const [problem, setProblem] = useState<string | undefined>(undefined);
  const [key] = useState(newIdempotencyKey);
  const radios = useRef<(HTMLButtonElement | null)[]>([]);
  const noteLength = [...note].length;

  const move = (from: number, step: number): void => {
    const next = (from + step + REPORT_REASONS.length) % REPORT_REASONS.length;
    const option = REPORT_REASONS[next];
    if (option === undefined) return;
    radios.current[next]?.focus();
    setReason(option);
  };

  const send = async (): Promise<void> => {
    if (reason === undefined || phase.kind !== 'choosing') return;
    setProblem(undefined);
    setPhase({ kind: 'sending' });
    // Somebody reporting what the AI wrote is not asked for a rating today.
    noteTrouble();
    try {
      await deliver(reason, note, key);
      setPhase({ kind: 'sent' });
    } catch (error) {
      setPhase({ kind: 'choosing' });
      setProblem(
        isApiError(error, 'offline')
          ? t('report.offline')
          : isApiError(error, 'tooMany')
            ? t('report.tooMany')
            : isApiError(error) && error.status === 404
              ? t('report.gone')
              : t('report.failed'),
      );
    }
  };

  if (phase.kind === 'sent') {
    return (
      <Sheet label={t('report.title')} onClose={onClose}>
        <div className={styles.sent} role="status">
          <span className={styles.sentMark} aria-hidden="true">
            <Icon name="check" size={22} weight={2.4} />
          </span>
          <p className={styles.sentTitle}>{t('report.thanks')}</p>
          <p className={styles.sentNote}>{t('report.thanksNote')}</p>
          <button type="button" className={styles.primary} onClick={onClose} autoFocus>
            {t('action.done')}
          </button>
        </div>
      </Sheet>
    );
  }

  const busy = phase.kind === 'sending';
  return (
    <Sheet title={t('report.title')} onClose={onClose}>
      <form
        className={styles.form}
        onSubmit={(event) => {
          event.preventDefault();
          void send();
        }}
      >
        <p className={styles.lead}>{lead ?? t('report.lead')}</p>

        <figure className={styles.quote}>
          <figcaption className={styles.kicker}>{t('report.what')}</figcaption>
          {target.surface === 'lex' && target.snapshot === '' ? (
            <p className={styles.quoteText}>{t('report.whatLex')}</p>
          ) : (
            // The model's words in whichever direction they run: a Persian
            // meaning starts at the right inside an English page.
            <p className={styles.quoteText} dir="auto">
              {target.snapshot}
            </p>
          )}
        </figure>

        <div className={styles.reasons} role="radiogroup" aria-labelledby={`${id}-reason`}>
          <p id={`${id}-reason`} className={styles.label}>
            {t('report.reasonLabel')}
          </p>
          {REPORT_REASONS.map((option, index) => {
            const on = option === reason;
            return (
              <button
                key={option}
                ref={(element) => {
                  radios.current[index] = element;
                }}
                type="button"
                role="radio"
                aria-checked={on}
                // Before a choice the first is the one Tab reaches.
                tabIndex={on || (reason === undefined && index === 0) ? 0 : -1}
                disabled={busy}
                className={cx(styles.reason, on && styles.reasonOn)}
                onClick={() => {
                  setReason(option);
                  setProblem(undefined);
                }}
                onKeyDown={(event) => {
                  if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
                    event.preventDefault();
                    move(index, 1);
                  } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
                    event.preventDefault();
                    move(index, -1);
                  }
                }}
              >
                <span className={styles.mark} aria-hidden="true">
                  {on && <span className={styles.dot} />}
                </span>
                {t(REASON_LABEL[option])}
              </button>
            );
          })}
        </div>

        <label className={styles.noteField}>
          <span className={styles.label}>{t('report.noteLabel')}</span>
          <textarea
            className={styles.note}
            value={note}
            rows={3}
            dir="auto"
            maxLength={REPORT_NOTE_MAX}
            placeholder={t('report.notePlaceholder')}
            disabled={busy}
            onChange={(event) => {
              setNote(event.target.value);
            }}
          />
          {noteLength >= NOTE_COUNT_FROM && (
            <span className={styles.count} aria-live="polite">
              {noteLength} / {REPORT_NOTE_MAX}
            </span>
          )}
        </label>

        {problem !== undefined && (
          <p className={styles.problem} role="alert">
            {problem}
          </p>
        )}

        <div className={styles.actions}>
          <button type="button" className={styles.secondary} onClick={onClose}>
            {t('action.cancel')}
          </button>
          <button type="submit" className={styles.primary} disabled={reason === undefined || busy}>
            {busy ? t('report.sending') : t('report.send')}
          </button>
        </div>
      </form>
    </Sheet>
  );
}
